import 'package:flutter/material.dart';
import 'core/network/api.dart';import 'core/theme/app_theme.dart';import 'features/auth/login_screen.dart';import 'features/complaints/complaint_screens.dart';import 'features/tasks/tasks_screen.dart';import 'features/notifications/notifications_screen.dart';import 'features/profile/profile_screen.dart';
void main(){WidgetsFlutterBinding.ensureInitialized();runApp(const ClyraApp());}
class ClyraApp extends StatefulWidget{const ClyraApp({super.key});@override State<ClyraApp> createState()=>_ClyraAppState();}
class _ClyraAppState extends State<ClyraApp>{final api=ClyraApi();bool ready=false;@override void initState(){super.initState();api.restore().whenComplete(()=>setState(()=>ready=true));}
@override Widget build(BuildContext context)=>MaterialApp(title:'Clyra',debugShowCheckedModeBanner:false,theme:ClyraTheme.light,home:!ready?const Scaffold(body:Center(child:CircularProgressIndicator())):api.currentUser==null?LoginScreen(api:api,onLogin:()=>setState((){})):MainShell(api:api,onLogout:()async{await api.logout();setState((){});}),);}
}
class MainShell extends StatefulWidget{const MainShell({super.key,required this.api,required this.onLogout});final ClyraApi api;final VoidCallback onLogout;@override State<MainShell> createState()=>_MainShellState();}
class _MainShellState extends State<MainShell>{int index=0;@override Widget build(BuildContext context){final role=widget.api.currentUser?['role'];final staff=role=='STAFF';final tabs=staff?['Home','Tasks','History','Profile']:['Home','My Complaints','Notifications','Profile'];final views=staff?[HomeScreen(api:widget.api,staff:true),TasksScreen(api:widget.api,history:false),TasksScreen(api:widget.api,history:true),ProfileScreen(api:widget.api,logout:widget.onLogout)]:[HomeScreen(api:widget.api,staff:false),ComplaintList(api:widget.api),NotificationsScreen(api:widget.api),ProfileScreen(api:widget.api,logout:widget.onLogout)];
return Scaffold(appBar:AppBar(title:const Text('clyra.',style:TextStyle(fontWeight:FontWeight.w900,letterSpacing:-1)),actions:[IconButton(icon:const Icon(Icons.notifications_none),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Scaffold(appBar:AppBar(title:const Text('Notifications')),body:NotificationsScreen(api:widget.api)))))]),body:IndexedStack(index:index,children:views),floatingActionButton:!staff&&index==0?FloatingActionButton.extended(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ReportScreen(api:widget.api))),label:const Text('Report issue'),icon:const Icon(Icons.add)):null,bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:[for(var i=0;i<tabs.length;i++)NavigationDestination(icon:Icon(i==0?Icons.home_outlined:i==1?(staff?Icons.assignment_outlined:Icons.description_outlined):i==2?(staff?Icons.history:Icons.notifications_outlined):Icons.person_outline),label:tabs[i])]),);}
}
class HomeScreen extends StatefulWidget{const HomeScreen({super.key,required this.api,required this.staff});final ClyraApi api;final bool staff;@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{late Future<dynamic> future;@override void initState(){super.initState();future=widget.api.get(widget.staff?'/assignments?limit=6':'/complaints?limit=6');}
@override Widget build(BuildContext context){final first=widget.api.currentUser?['fullName']?.toString().split(' ').first??'Campus member';return ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(gradient:const LinearGradient(colors:[ClyraTheme.navy,ClyraTheme.indigo]),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('YOUR CAMPUS, CONNECTED',style:TextStyle(color:ClyraTheme.teal,fontSize:12,fontWeight:FontWeight.bold,letterSpacing:1)),const SizedBox(height:12),Text('Hello, $first',style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800,color:Colors.white)),const SizedBox(height:8),Text(widget.staff?'Stay ahead of assigned tasks and progress.':'Every issue has a clear path to resolution.',style:const TextStyle(color:Colors.white70)),const SizedBox(height:12)])),const SizedBox(height:24),Text(widget.staff?'Your recent assignments':'Your recent complaints',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),FutureBuilder<dynamic>(future:future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Text('Unable to load data: ${s.error}');final data=(s.data as List?)??[];if(data.isEmpty)return const Card(child:Padding(padding:EdgeInsets.all(22),child:Text('No reports or tasks yet.')));return Column(children:[for(final item in data)Card(child:ListTile(title:Text((item['title']??item['remarks']??'Assigned task').toString()),subtitle:Text((item['complaintCode']??item['assignmentStatus']??'').toString()),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ComplaintDetail(api:widget.api,complaintId:(widget.staff?item['complaintId']:item['_id']).toString())))))]);})]);}
}
